  ss9n2 = char_center_sums[(8, 1, 2)](evaluate(tt, [k1, k4, k3, k2], [k1, k1, k2, k3]))
  ss10n1 = char_center_sums[(9, 1, 1)](
    evaluate(tt, [k1, k3, k4, k2], [k1, k2, k4, k3 * (q - 1)])
  )
  ss11n1 = char_center_sums[(9, 1, 2)](evaluate(tt, [k2, k3, k4, k1], [k2, k3, k3, k1]))
  erg - ss1n1 - ss2n1 - ss2n2 - ss3n1 - ss3n2 - ss3n3 - ss4n1 - ss4n2 - ss5n1 - ss6n1 -
  ss7n1 - ss7n2 - ss7n3 - ss7n4 - ss8n1 - ss9n1 - ss9n2 - ss10n1 - ss11n1
end
char_center_sums[(9, 1, 4)] = function (tt::Union{GenericCyclo,GenericCycloFrac})
  erg = tt
  erg = nesum(erg, k1, 0, q^2 - 2)
  erg = nesum(erg, k2, 0, q^2 - 2)
  ss1n1 = char_center_sums[(1, 1, 1)](evaluate(tt, [k2, k1], [k1 * (q - 1), k1 * (q - 1)]))
  ss2n1 = char_center_sums[(3, 1, 1)](evaluate(tt, [k2, k1], [k2 * (q - 1), k1 * (q - 1)]))
  ss3n1 = char_center_sums[(4, 1, 2)](evaluate(tt, [k1, k2], [k1, -q * k1]))
  ss3n2 = char_center_sums[(4, 1, 2)](evaluate(tt, [k1, k2], [k1, k1]))
  ss4n1 = char_center_sums[(5, 1, 2)](evaluate(tt, [k2, k1], [k2, k1 * (q - 1)]))
  ss5n1 = char_center_sums[(7, 1, 2)](evaluate(tt, [k1, k2], [k1, k2 * (q - 1)]))
  erg - ss1n1 - ss2n1 - ss3n1 - ss3n2 - ss4n1 - ss5n1
end
char_center_sums[(9, 1, 1)] = function (tt::Union{GenericCyclo,GenericCycloFrac})
  erg = tt
  erg = nesum(erg, k1, 0, q)
  erg = nesum(erg, k2, 0, q)
  erg = nesum(erg, k3, 0, q)
  erg = nesum(erg, k4, 0, q)
  ss1n1 = char_center_sums[(1, 1, 1)](evaluate(tt, [k2, k1, k3, k4], [k1, k1, k1, k1]))
  ss2n1 = char_center_sums[(2, 1, 1)](evaluate(tt, [k2, k1, k3, k4], [k1, k1, k1, k2]))
  ss2n2 = char_center_sums[(2, 1, 1)](evaluate(tt, [k2, k1, k3, k4], [k2, k1, k1, k1]))
  ss3n1 = char_center_sums[(3, 1, 1)](evaluate(tt, [k2, k1, k3, k4], [k2, k1, k1, k2]))
  ss3n2 = char_center_sums[(3, 1, 1)](evaluate(tt, [k3, k2, k1, k4], [k2, k1, k1, k1]))
  ss3n3 = char_center_sums[(3, 1, 1)](evaluate(tt, [k1, k2, k3, k4], [k2, k1, k1, k1]))
  ss4n1 = char_center_sums[(4, 1, 1)](evaluate(tt, [k2, k3, k1, k4], [k2, k2, k1, k1]))
  ss4n2 = char_center_sums[(4, 1, 1)](evaluate(tt, [k3, k2, k1, k4], [k2, k1, k1, k2]))
  ss5n1 = char_center_sums[(5, 1, 1)](evaluate(tt, [k1, k3, k2, k4], [k1, k1, k3, k2]))
  ss6n1 = char_center_sums[(6, 1, 1)](evaluate(tt, [k4, k3, k1, k2], [k1, k2, k1, k3]))
  ss6n2 = char_center_sums[(6, 1, 1)](evaluate(tt, [k1, k4, k3, k2], [k2, k1, k1, k3]))
  ss6n3 = char_center_sums[(6, 1, 1)](evaluate(tt, [k2, k4, k3, k1], [k1, k3, k2, k1]))
  ss6n4 = char_center_sums[(6, 1, 1)](evaluate(tt, [k2, k4, k1, k3], [k1, k3, k2, k1]))
  ss7n1 = char_center_sums[(7, 1, 1)](evaluate(tt, [k1, k3, k2, k4], [k1, k3, k2, k2]))
  erg - ss1n1 - ss2n1 - ss2n2 - ss3n1 - ss3n2 - ss3n3 - ss4n1 - ss4n2 - ss5n1 - ss6n1 -
  ss6n2 - ss6n3 - ss6n4 - ss7n1
end
char_center_sums[(10, 1, 3)] = function (tt::Union{GenericCyclo,GenericCycloFrac})
  erg = tt
  erg = nesum(erg, k1, 0, q)
  erg = nesum(erg, k2, 0, q^3)
  erg = nesum(erg, k3, 0, q)
  ss1n1 = char_center_sums[(1, 1, 1)](
    evaluate(tt, [k3, k2, k1], [k1, k1 * (q^2 - q + 1), k1])
  )
  ss2n1 = char_center_sums[(2, 1, 1)](
    evaluate(tt, [k2, k1, k3], [k1 * (q^2 - q + 1), k1, k2])
  )
  ss3n1 = char_center_sums[(3, 1, 1)](
    evaluate(tt, [k3, k2, k1], [k1, k1 * (q^2 - q + 1), k2])
  )
  ss4n1 = char_center_sums[(4, 1, 1)](
    evaluate(tt, [k3, k1, k2], [k1, k1, k2 * (q^2 - q + 1)])
  )
  ss5n1 = char_center_sums[(6, 1, 1)](
    evaluate(tt, [k3, k2, k1], [k3, k1 * (q^2 - q + 1), k2])
  )
  ss6n1 = char_center_sums[(8, 1, 3)](evaluate(tt, [k2, k3, k1], [k2, k1, k1]))
  erg - ss1n1 - ss2n1 - ss3n1 - ss4n1 - ss5n1 - ss6n1
end
char_center_sums[(7, 1, 2)] = function (tt::Union{GenericCyclo,GenericCycloFrac})
  erg = tt
  erg = nesum(erg, k1, 0, q^2 - 2)
  erg = nesum(erg, k2, 0, q)
  ss1n1 = char_center_sums[(1, 1, 1)](evaluate(tt, [k1, k2], [k1 * (q - 1), k1]))
  ss2n1 = char_center_sums[(3, 1, 1)](evaluate(tt, [k1, k2], [k1 * (q - 1), k2]))
  erg - ss1n1 - ss2n1
end

